<script setup lang="ts">
import {describeLiveFailure} from '~/features/live-core/gateway';import type{PublicPlan}from'~/features/entry-live/gateway';
useSeoMeta({title:'产品套餐｜语赞心声'});const gateway=useEntryLiveGateway();const state=ref<'loading'|'ready'|'empty'|'error'>('loading');const plans=ref<PublicPlan[]>([]);const failure=ref<ReturnType<typeof describeLiveFailure>|null>(null);async function load(){state.value='loading';try{plans.value=await gateway.plans();state.value=plans.value.length?'ready':'empty'}catch(error){failure.value=describeLiveFailure(error);state.value='error'}}await load();
</script>
<template><section class="plans" aria-labelledby="plans-title"><header class="plans__hero"><div class="yx-shell"><p class="yx-kicker">PUBLIC PLANS · LIVE CATALOG</p><h1 id="plans-title">把选择说清楚，<br>不把报价编出来。</h1><p>套餐、价格与服务范围只采用 `/plans` 返回值。咨询和试用写接口尚未就绪。</p></div></header><div class="yx-shell plans__body"><section v-if="state==='loading'" class="state" aria-live="polite"><h2>正在读取套餐配置……</h2></section><section v-else-if="state==='error'" class="state" role="alert"><p class="yx-kicker">{{failure?.code||failure?.kind}}</p><h2>{{failure?.message}}</h2><button type="button" @click="load">重试</button></section><section v-else-if="state==='empty'" class="empty"><p class="yx-kicker">REAL EMPTY · HTTP 200</p><div class="empty__mark" aria-hidden="true">00</div><div><h2>当前没有已发布套餐。</h2><p>这是后端返回的真实空列表。页面没有采用 VM 中的演示价格，也不会把咨询或试用显示为已提交。</p><NuxtLink to="/login">已有账号，前往登录</NuxtLink></div></section><template v-else><section class="catalog"><p class="yx-kicker">AVAILABLE NOW</p><ol><li v-for="(plan,index) in plans" :key="plan.id"><b>{{String(index+1).padStart(2,'0')}}</b><div><span>{{plan.status||'AVAILABLE'}}</span><h2>{{plan.name||plan.title||'未命名套餐'}}</h2><p>{{plan.description||'后端未返回说明。'}}</p><strong v-if="plan.priceLabel">{{plan.priceLabel}}</strong><small v-else>价格未配置</small></div></li></ol></section></template><aside class="waiting"><p class="yx-kicker">WAITING BACKEND</p><h2>咨询与试用尚未接入写接口</h2><p>我们保留完整入口说明，但不会记录表单后伪造“提交成功”。</p><div><button type="button" disabled>咨询方案 · 暂不可用</button><button type="button" disabled>申请试用 · 暂不可用</button></div></aside></div></section></template>
